package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicDecimalDivisorsTest {
 private static Question q(String prompt){return new Question("decimalDiv",prompt,"private expression","999");}
 private static Checker.Result check(Question q,String value){return new Checker().check(q,List.of(),Collections.singletonList(value));}
 @Test public void PublicOriginalsDetermineExactFiniteAndFractionAnswersWithoutStoredKeys(){
  for(String[] row:new String[][]{{"3.24 ÷ 0.8","4.05"},{"3.24/0.8","4.05"},{"8/3","8/3"},{"0.001 / 6.4","0.00015625"},{"3.24 ÷ 0.7","162/35"},{"0.000 ÷ 0.3","0"},{"100.0001 ÷ 0.0001","1000001"},{"2 ÷ 3","2/3"},{"00012.3400 ÷ 000002.50","4.936"}}){Question q=q(row[0]);q.kind="complexRoots";var original=DecimalDivisorQuotients.readGeneral(q);assertNotNull(original);assertEquals(DecimalDivisorQuotients.numericInput(row[1]),original.value());assertTrue(check(q,row[1]).correct());assertEquals(Checker.Status.WRONG_ANSWER,check(q,"999").status);q.answers=null;q.expression=null;assertTrue(check(q,row[1]).correct());assertTrue(CurriculumLimits.NONE.allows(q));assertNull(q.answers);assertNull(q.expression);assertEquals("complexRoots",q.kind);assertNotNull(HelpPlan.forQuestion(q));assertTrue(new Checker().checkSteps(q,List.of(row[0].replace("÷","/")+"="+row[1]),List.of(Checker.StepKind.FULL)).correct());}
  var raw=DecimalDivisorQuotients.readGeneral(q("00012.3400 ÷ 000002.50"));assertEquals("00012.3400",raw.leftRaw());assertEquals("000002.50",raw.rightRaw());assertTrue(raw.finitePossible());assertFalse(DecimalDivisorQuotients.readGeneral(q("1 ÷ 3")).finitePossible());
 }
 @Test public void FinitePublicGuideKeepsEveryLegacyFrameAndDoesNotMutateStoredGuide(){
  for(String prompt:List.of("3.24 ÷ 0.8","12.3400 / 2.50","0.000 ÷ 0.3","2 ÷ 1")){Question q=q(prompt);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;Question prior=q(prompt);DecimalArithmeticRelations.attach(prior);StudyGuide g=DecimalDivisorQuotients.guide(q);assertEquals(7,g.frames.size());assertEquals("decimal-arithmetic-relations-v1",g.teachingVersion);for(int i=0;i<7;i++){var actual=g.frames.get(i);var old=prior.studyGuide.frames.get(i);assertEquals(old.instruction,actual.instruction);assertEquals(old.before,actual.before);assertEquals(old.after,actual.after);assertEquals(old.expected,actual.expected);assertEquals(old.inputFormat,actual.inputFormat);}HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertFalse(h.canTransfer());HelpPlan.Draft d=h.restore(null,q.id);d.entries=new ArrayList<>(g.frames.stream().map(f->f.expected).toList());d.stage=7;HelpPlan.Draft restored=h.restore(d.copy(),q.id);assertEquals(7,restored.stage);assertEquals(g.teachingVersion,restored.teachingVersion);assertEquals(DecimalDivisorQuotients.value(q),DecimalDivisorQuotients.numericInput(h.enteredAnswer(restored)));assertSame(stored,q.studyGuide);assertEquals("private expression",q.expression);assertArrayEquals(new String[]{"999"},q.answers);}
 }
 @Test public void GeneralNonterminatingNineStepGuideAndCheckedReferencesProduceExactFraction(){
  Question q=q("3.24 ÷ 0.7");StudyGuide g=DecimalDivisorQuotients.guide(q);HelpPlan h=HelpPlan.forQuestion(q);assertEquals("decimal-divisor-quotient-v1",g.teachingVersion);assertEquals(9,h.size());assertFalse(h.canTransfer());List<String> entries=List.of("3.240","0.70","2","100","324","70","2","162","35");for(int i=0;i<9;i++)assertTrue("stage"+i,h.step(i).accepts(entries.get(i)));assertFalse(h.step(0).accepts("81/25"));assertFalse(h.step(1).accepts("7/10"));assertTrue(h.step(7).accepts("324/2"));assertEquals(Map.of("옮긴 왼쪽 수 A = x × u = ","324","옮긴 오른쪽 수 B = y × u = ","70"),DecimalDivisorQuotients.references(q,6,entries));assertEquals(Map.of("옮긴 왼쪽 수 A = x × u = ","324","최대공약수 g = gcd(A, B) = ","2"),DecimalDivisorQuotients.references(q,7,entries));List<String> wrong=new ArrayList<>(entries);wrong.set(4,"325");assertEquals(Map.of("최대공약수 g = gcd(A, B) = ","2"),DecimalDivisorQuotients.references(q,7,wrong));assertTrue(DecimalDivisorQuotients.references(q,0,entries).isEmpty());assertTrue(DecimalDivisorQuotients.references(q,9,entries).isEmpty());assertTrue(DecimalDivisorQuotients.references(null,1,entries).isEmpty());HelpPlan.Draft d=h.restore(null,q.id);d.entries=new ArrayList<>(entries);d.stage=9;assertEquals("162/35",h.enteredAnswer(h.restore(d.copy(),q.id)));assertNull(q.studyGuide);
  Question finite=q("3.24 ÷ 0.8");List<String> values=List.of("3.240","0.80","1","10","32.4","8");assertEquals(Map.of("옮긴 왼쪽 수 A = x × u = ","32.4","옮긴 오른쪽 수 B = y × u = ","8"),DecimalDivisorQuotients.references(finite,6,values));assertEquals(3,DecimalDivisorQuotients.references(finite,4,values).size());
 }
 @Test public void LongExactFiniteAndLargeFractionHelpRemainReachableWithoutSharedGuardWidening(){
  Question finite=q("0.000000000001 ÷ 590295810.358705651712");Rational expected=new Rational(BigInteger.ONE,BigInteger.ONE.shiftLeft(69));String decimal=BigDecimal.ONE.divide(new BigDecimal(BigInteger.ONE.shiftLeft(69))).toPlainString();assertEquals(expected,DecimalDivisorQuotients.value(finite));assertTrue(check(finite,decimal).correct());HelpPlan h=HelpPlan.forQuestion(finite);StudyGuide g=DecimalDivisorQuotients.guide(finite);assertEquals(7,h.size());for(int i=0;i<h.size();i++)assertTrue(h.step(i).accepts(g.frames.get(i).expected));assertTrue(h.step(6).accepts(decimal));assertTrue(DecimalDivisorQuotients.references(finite,6,List.of("0.000000000001","590295810.358705651712","12","1000000000000","1","590295810358705651712")).containsValue("590295810358705651712"));try{Expression.number(decimal);fail("Shared twelve-place guard changed");}catch(IllegalArgumentException expectedGuard){}
  Question fraction=q("999999999.999999999999 ÷ 0.000000000007");StudyGuide fg=DecimalDivisorQuotients.guide(fraction);HelpPlan fh=HelpPlan.forQuestion(fraction);assertEquals(9,fh.size());HelpPlan.Draft d=fh.restore(null,fraction.id);d.entries=new ArrayList<>(fg.frames.stream().map(f->f.expected).toList());d.stage=9;assertEquals("999999999999999999999/7",fh.enteredAnswer(d));assertTrue(check(fraction,fh.enteredAnswer(d)).correct());assertFalse(fh.step(7).accepts("1".repeat(121)));assertNull(DecimalDivisorQuotients.numericInput("1".repeat(121)));
 }
 @Test public void OptionalFullAndPartialWorkKeepPublicAnchorAndWorkErrorOwnership(){
  Question q=q("3.24 ÷ 0.8");q.kind="radical";q.calculationMethod="written";Checker c=new Checker();assertTrue(c.check(q,List.of("3.24/0.8=4.05"),List.of("4.05"),List.of(Checker.StepKind.FULL)).correct());assertTrue(c.checkSteps(q,List.of("3.24/0.8=4.05"),List.of(Checker.StepKind.FULL)).correct());Checker.Result wrong=c.check(q,List.of("999=999"),List.of("4.05"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.WRONG_STEP,wrong.status);assertEquals(Checker.InputTarget.WORK,wrong.inputTarget);Checker.Result incomplete=c.check(q,List.of("3.24/0.8="),List.of("4.05"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.INPUT_NEEDED,incomplete.status);assertEquals(Checker.InputTarget.WORK,incomplete.inputTarget);assertTrue(c.check(q,List.of("2*3=6"),List.of("4.05"),List.of(Checker.StepKind.PARTIAL)).correct());q.stepSupport=false;assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of("3.24/0.8=4.05"),List.of("4.05"),List.of(Checker.StepKind.FULL)).status);assertEquals("private expression",q.expression);assertEquals("radical",q.kind);
 }
 @Test public void MalformedPublicSourcesAndDeclaredFormatsCannotUseCachedFallback(){
  for(String prompt:List.of("1 ÷ 0","1 ÷ 0.000","1000000000 ÷ 0.1","1 ÷ 1000000000","1.2345678901234 ÷ 0.1","1 ÷ 0.1234567890123","-1 ÷ 0.2","1e2 ÷ 0.2","1. ÷ 0.2","1 ÷ .2","1/2 ÷ 0.2","1 ÷ 0.2 ÷ 2","1 × 0.2")){Question q=q(prompt);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;assertNull(DecimalDivisorQuotients.readGeneral(q));assertNull(DecimalDivisorQuotients.value(q));assertNull(DecimalDivisorQuotients.guide(q));assertNull(HelpPlan.forQuestion(q));assertNull(DecimalDivisorQuotients.workQuestion(q));assertSame(stored,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,check(q,"999").status);assertFalse(CurriculumLimits.NONE.allows(q));}
  Question q=q("0.5 ÷ 0.5");q.answerFormat="decimalValue";assertTrue(check(q,"1").correct());assertTrue(check(q," 1 . 0 ").correct());assertEquals(Checker.Status.INPUT_NEEDED,check(q,"1÷1").status);q.answerFormat="decimal";assertEquals(Checker.Status.INPUT_NEEDED,check(q,"1").status);assertTrue(check(q,"1.0").correct());q.answerFormat="fraction";assertEquals(Checker.Status.INPUT_NEEDED,check(q,"1").status);assertTrue(check(q,"2/2").correct());q.answerFormat="";assertTrue(check(q,"1/1").correct());for(String invalid:List.of("1e0","1+0","1,0","1.","1/0","1".repeat(121),"1".repeat(241)))assertEquals(Checker.Status.INPUT_NEEDED,check(q,invalid).status);assertNull(DecimalDivisorQuotients.numericInput(null));assertFalse(DecimalDivisorQuotients.acceptsStep("1÷1","1","decimalValue"));assertFalse(DecimalDivisorQuotients.acceptsStep("1÷1","1","decimal"));assertTrue(DecimalDivisorQuotients.acceptsStep("1÷1","1",""));assertNull(DecimalDivisorQuotients.readGeneral(null));assertNull(DecimalDivisorQuotients.readGeneral(new Question("decimalDivInt","1 ÷ 2","","0.5")));
 }
}
